</style>
<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script id="rampart-strategy">
function createStrategy() {
  return { plan(s) {
    const actions = [];
    let gold = s.gold;
    for (const pad of s.slots) if (!pad.turret && gold >= 50) {
      actions.push({op:"build",slot:pad.slot,type:"bolt"});
      gold -= 50;
    }
    return actions;
  } };
}
</script>
<script id="rampart-sim">
function rampartSimulate(createStrategy, seed, maxTicks, record = null) {
  const ground = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const air = [[0,6],[21,6],[21,11],[23,11]];
  function makeRoute(points) {
    let distance = 0;
    return points.slice(1).map(([x,y],i) => {
      const [fromX,fromY] = points[i];
      const length = 100 * (Math.abs(x-fromX) + Math.abs(y-fromY));
      const segment = {start:distance, end:distance+length, x:100*fromX+50, y:100*fromY+50,
        dx:Math.sign(x-fromX), dy:Math.sign(y-fromY)};
      distance += length;
      return segment;
    });
  }
  const routes = [makeRoute(ground), makeRoute(air)];
  const coordinates = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const slots = coordinates.map(([x,y],slot) => ({slot,x:100*x+50,y:100*y+50,turret:null}));
  const weapons = [
    ["bolt",50,26,8,300,0,0,false,3], ["cannon",90,60,24,260,90,0,false,1],
    ["frost",70,10,12,240,0,30,false,3], ["lance",120,180,36,360,0,0,true,1],
    ["flak",80,40,10,320,70,0,false,2]
  ].map(([type,cost,damage,period,range,splash,slow,pierce,domains],index) =>
    ({type,cost,damage,period,range,splash,slow,pierce,domains,index}));
  const monsters = [
    ["grunt",60,10,4,1,0,1,10], ["runner",40,20,4,1,0,2,4], ["wisp",50,12,6,2,1,3,3],
    ["brute",150,6,9,3,0,4,3], ["splitter",90,8,6,2,0,6,2], ["mender",70,8,7,2,0,8,1],
    ["splitling",0,12,1,1,0,Infinity,0]
  ].map(([type,hp,speed,bounty,leak,air,first,weight]) => ({type,hp,speed,bounty,leak,air,first,weight}));
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ''^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const draw = mulberry32(seed), strategy = createStrategy(), log = [], multipliers = [0,1000];
  const enemies = [], spawns = new Map();
  let gold = 250, baseHp = 10, wave = 0, tick = 0, fallTick = -1, nextId = 1;
  function composition(w) {
    const types = monsters.filter(e => e.first <= w);
    const weight = types.reduce((sum,e) => sum+e.weight, 0);
    return Array.from({length:4+Math.floor(3*w/5)}, () => {
      let r = draw()%weight;
      for (const e of types) {
        if (r < e.weight) return e;
        r -= e.weight;
      }
    });
  }
  let upcoming = composition(1);
  function reposition(enemy) {
    const route = routes[enemy.air];
    let segment = route.find(s => enemy.progress < s.end) || route[route.length-1];
    const offset = Math.min(enemy.progress,segment.end)-segment.start;
    enemy.x = segment.x+segment.dx*offset;
    enemy.y = segment.y+segment.dy*offset;
    enemy.dx = segment.dx;
    enemy.dy = segment.dy;
    enemy.remaining = route[route.length-1].end-enemy.progress;
  }
  function spawn(kind,w,progress=0,maxHp=Math.floor(kind.hp*multipliers[w]/1000)) {
    const {type,speed,bounty,leak,air} = kind;
    const enemy = {id:nextId++,type,speed,bounty,leak,air,w,progress,maxHp,hp:maxHp,age:0,slow:0,
      armor:type==="grunt" ? Math.floor(w/4) : type==="brute" ? 6+w : 0};
    reposition(enemy);
    enemies.push(enemy);
  }
  function view({id,type,hp,maxHp,x,y,air,armor,speed,slow,remaining}) {
    return {id,type,hp,maxHp,x,y,air,armor,speed,slowed:slow>0,remaining};
  }
  function distance(a,b) { return (a.x-b.x)**2+(a.y-b.y)**2; }
  function compatible(t,e) { return t.domains & (1<<e.air); }
  for (; tick<maxTicks; tick++) {
    const effects = record ? [] : null;
    if (tick>=20 && (tick-20)%40===0) {
      ++wave;
      if (wave>1) multipliers[wave] = Math.floor(multipliers[wave-1]*108/100);
      gold += Math.min(50,Math.floor(gold*5/100))+10+2*wave;
      const current = upcoming;
      upcoming = composition(wave+1);
      const actions = strategy.plan({tick,wave,gold,baseHp,
        slots:slots.map(({slot,x,y,turret}) => ({slot,x,y,turret:turret ? {type:turret.type,tier:turret.tier,spent:turret.spent}:null})),
        enemies:enemies.map(view),nextWave:upcoming.map(e=>e.type)});
      effects?.push({kind:"wave"});
      if (Array.isArray(actions)) for (const action of actions.slice(0,32)) {
        if (!action || !Number.isInteger(action.slot) || !slots[action.slot]) continue;
        const pad = slots[action.slot], turret = pad.turret;
        if (action.op==="build" && !turret) {
          const weapon = weapons.find(w=>w.type===action.type);
          if (!weapon || gold<weapon.cost) continue;
          gold -= weapon.cost;
          pad.turret = {...weapon,tier:1,spent:weapon.cost,cooldown:0,aim:Math.PI};
          log.push([tick,"B",pad.slot,weapon.index]);
          effects?.push({kind:"build",x:pad.x,y:pad.y,type:weapon.type});
        } else if (action.op==="upgrade" && turret && turret.tier<3) {
          const cost = turret.cost*turret.tier;
          if (gold<cost) continue;
          gold -= cost;
          turret.spent += cost;
          turret.tier++;
          turret.range += 30;
          turret.damage = Math.floor(turret.damage*16/10);
          log.push([tick,"U",pad.slot,turret.tier]);
          effects?.push({kind:"upgrade",x:pad.x,y:pad.y,type:turret.type});
        } else if (action.op==="sell" && turret) {
          gold += Math.floor(turret.spent*70/100);
          pad.turret = null;
          log.push([tick,"S",pad.slot,0]);
          effects?.push({kind:"sell",x:pad.x,y:pad.y,type:turret.type});
        }
      }
      current.forEach((kind,i) => {
        const due = tick+4*i;
        if (!spawns.has(due)) spawns.set(due,[]);
        spawns.get(due).push([kind,wave]);
      });
    }
    const due = spawns.get(tick);
    if (due) {
      for (const [kind,w] of due) spawn(kind,w);
      spawns.delete(tick);
    }
    for (let i=0; i<enemies.length;) {
      const e = enemies[i];
      e.progress += e.slow ? Math.floor(e.speed*60/100) : e.speed;
      reposition(e);
      if (e.remaining>0) { i++; continue; }
      enemies.splice(i,1);
      baseHp -= e.leak;
      log.push([tick,"L",e.id,baseHp]);
      effects?.push({kind:"leak",x:e.x,y:e.y,hp:baseHp});
      if (baseHp<=0) {
        fallTick = tick;
        log.push([tick,"F",wave,0]);
        effects?.push({kind:"fall",x:e.x,y:e.y});
        break;
      }
    }
    if (fallTick<0) {
      for (const e of enemies) {
        e.age++;
        if (e.type!=="mender" || e.age%20!==0) continue;
        for (const ally of enemies) if (distance(e,ally)<=150**2) {
          ally.hp = Math.min(ally.maxHp,ally.hp+Math.floor(ally.maxHp*8/100));
        }
        effects?.push({kind:"heal",x:e.x,y:e.y});
      }
      for (const pad of slots) {
        const t = pad.turret;
        if (!t || (t.cooldown>0 && --t.cooldown>0)) continue;
        const candidates = enemies.filter(e=>compatible(t,e) && distance(pad,e)<=t.range**2);
        if (!candidates.length) continue;
        const picked = strategy.target?.({slot:pad.slot,type:t.type,tier:t.tier,x:pad.x,y:pad.y,range:t.range},candidates.map(view));
        const target = candidates.find(e=>e.id===picked) || candidates.reduce((a,b)=>b.remaining<a.remaining?b:a);
        t.cooldown = t.period;
        if (effects) t.aim = Math.atan2(target.x-pad.x,target.y-pad.y);
        effects?.push({kind:"shot",type:t.type,x:pad.x,y:pad.y,tx:target.x,ty:target.y,air:target.air});
        const victims = t.splash ? enemies.filter(e=>compatible(t,e) && distance(target,e)<=t.splash**2) : [target];
        for (const e of victims) {
          e.hp -= Math.max(1,t.damage-(t.pierce?0:e.armor));
          if (t.slow) e.slow = t.slow;
        }
        for (let i=0; i<enemies.length;) {
          const e = enemies[i];
          if (e.hp>0) { i++; continue; }
          enemies.splice(i,1);
          gold += e.bounty;
          log.push([tick,"K",e.id,pad.slot]);
          effects?.push({kind:"kill",type:e.type,x:e.x,y:e.y,air:e.air});
          if (e.type==="splitter") for (let j=0;j<3;j++) spawn(monsters[6],e.w,e.progress,Math.max(1,Math.floor(e.maxHp/4)));
        }
      }
      for (const e of enemies) if (e.slow>0) e.slow--;
    }
    if (record) record(tick,{wave,gold,baseHp,next:upcoming.map(e=>e.type),
      turrets:slots.map(p=>p.turret && {type:p.turret.type,tier:p.turret.tier,aim:p.turret.aim}),
      enemies:enemies.map(e=>({...view(e),dx:e.dx,dy:e.dy})),effects});
    if (fallTick>=0) break;
  }
  const data = JSON.stringify(log);
  let hash = 0x811c9dc5;
  for (let i=0;i<data.length;i++) hash = Math.imul(hash''^data.charCodeAt(i),0x01000193);
  return {score:Math.round(((fallTick<0?maxTicks:fallTick)-20)*2.5)/100,
    fallTick,log,hash:(hash>>>0).toString(16).padStart(8,"0")};
}
</script>
</head>
<body>
<canvas id="stage"></canvas>
<div id="countdown" aria-hidden="true">3</div>

<div id="dock" role="toolbar" aria-label="Simulation Controls">
  <button id="btn-refire" type="button" aria-label="Re-fire" title="Re-fire">
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.19"/>
    </svg>
    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="100" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>
EOF
